import{_ as i,c as t,o as n,ae as a}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"Web Link Manager User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Content/web-links.md","filePath":"Administration/AI-Management/Content/web-links.md"}'),o={name:"Administration/AI-Management/Content/web-links.md"};function l(r,e,s,c,h,d){return n(),t("div",null,e[0]||(e[0]=[a('<h1 id="web-link-manager-user-guide" tabindex="-1">Web Link Manager User Guide <a class="header-anchor" href="#web-link-manager-user-guide" aria-label="Permalink to &quot;Web Link Manager User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#web-link-manager-user-guide">Web Link Manager User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-web-link-manager">Accessing Web Link Manager</a></li><li><a href="#web-link-manager-interface-overview">Web Link Manager Interface Overview</a></li><li><a href="#creating-web-links">Creating Web Links</a><ul><li><a href="#basic-link-information">Basic Link Information</a></li><li><a href="#icon-configuration">Icon Configuration</a></li><li><a href="#theme-specific-styling">Theme-Specific Styling</a></li></ul></li><li><a href="#icon-customization">Icon Customization</a><ul><li><a href="#selecting-an-icon">Selecting an Icon</a></li><li><a href="#customizing-icon-colors">Customizing Icon Colors</a></li><li><a href="#light-and-dark-mode-settings">Light and Dark Mode Settings</a></li></ul></li><li><a href="#knowledge-base-integration">Knowledge Base Integration</a></li><li><a href="#publishing-configuration">Publishing Configuration</a><ul><li><a href="#tags-and-topics">Tags and Topics</a></li><li><a href="#publishing-schedule">Publishing Schedule</a></li></ul></li><li><a href="#featured-content-configuration">Featured Content Configuration</a><ul><li><a href="#featured-content-settings">Featured Content Settings</a></li><li><a href="#featured-content-preview">Featured Content Preview</a></li></ul></li><li><a href="#managing-existing-links">Managing Existing Links</a><ul><li><a href="#editing-links">Editing Links</a></li><li><a href="#deleting-links">Deleting Links</a></li></ul></li><li><a href="#metadata-and-information">Metadata and Information</a></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Web Link Manager allows you to create and manage hyperlinks to external websites and applications, complete with customized icons and styling. These links can be used throughout the AI Assistant platform and in LaunchPad interfaces, providing users with quick access to important resources. This guide explains how to create, customize, and manage web links effectively.</p><h2 id="accessing-web-link-manager" tabindex="-1">Accessing Web Link Manager <a class="header-anchor" href="#accessing-web-link-manager" aria-label="Permalink to &quot;Accessing Web Link Manager&quot;">​</a></h2><p>The Web Link Manager is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to the Content section in the main menu</li><li>Select &quot;Add&quot; and choose &quot;Create Web Link&quot;</li><li>Or, select an existing web link from the Content Manager to edit it</li></ol><h2 id="web-link-manager-interface-overview" tabindex="-1">Web Link Manager Interface Overview <a class="header-anchor" href="#web-link-manager-interface-overview" aria-label="Permalink to &quot;Web Link Manager Interface Overview&quot;">​</a></h2><p>The Web Link Manager consists of these key sections:</p><ol><li><strong>Header Bar</strong>: Contains the title, help button, and action buttons (Save, Delete, Done)</li><li><strong>Link Configuration Panel</strong>: Where you configure the link title, description, and URL</li><li><strong>Icon Styler</strong>: Tools to customize icon appearance for light and dark themes</li><li><strong>Publish Attributes Panel</strong>: Controls for tags, topics, scheduling, and featured content settings</li></ol><h2 id="creating-web-links" tabindex="-1">Creating Web Links <a class="header-anchor" href="#creating-web-links" aria-label="Permalink to &quot;Creating Web Links&quot;">​</a></h2><h3 id="basic-link-information" tabindex="-1">Basic Link Information <a class="header-anchor" href="#basic-link-information" aria-label="Permalink to &quot;Basic Link Information&quot;">​</a></h3><p>To configure the fundamental link details:</p><ol><li><p><strong>Web Link Title</strong>: Enter a descriptive name for the link</p><ul><li>This appears as the title beneath the icon</li><li>Should be concise but descriptive</li></ul></li><li><p><strong>Link Description</strong>: Provide context about the link&#39;s purpose</p><ul><li>Explain why someone would use this web link</li><li>This helps the AI understand and suggest the link appropriately</li></ul></li><li><p><strong>Link URL</strong>: Enter the complete web address</p><ul><li>Must include https:// or http:// prefix</li><li>Will be validated to ensure it&#39;s a properly formatted URL</li></ul></li></ol><h3 id="icon-configuration" tabindex="-1">Icon Configuration <a class="header-anchor" href="#icon-configuration" aria-label="Permalink to &quot;Icon Configuration&quot;">​</a></h3><p>Each link has a visual icon that represents it in the interface:</p><ol><li>The default icon appears in the preview box at the top of the form</li><li>Click on the icon or preview box to open the Icon Picker dialog</li><li>The icon appears within a customizable container that can be styled separately</li></ol><h3 id="theme-specific-styling" tabindex="-1">Theme-Specific Styling <a class="header-anchor" href="#theme-specific-styling" aria-label="Permalink to &quot;Theme-Specific Styling&quot;">​</a></h3><p>Links can have different appearances in light and dark modes:</p><ol><li>Use the Light/Dark toggle button to switch between theme configurations</li><li>Configure colors independently for each theme</li><li>Changes in one theme don&#39;t affect the other theme&#39;s settings</li></ol><h2 id="icon-customization" tabindex="-1">Icon Customization <a class="header-anchor" href="#icon-customization" aria-label="Permalink to &quot;Icon Customization&quot;">​</a></h2><h3 id="selecting-an-icon" tabindex="-1">Selecting an Icon <a class="header-anchor" href="#selecting-an-icon" aria-label="Permalink to &quot;Selecting an Icon&quot;">​</a></h3><p>To choose an icon for your link:</p><ol><li>Click on the icon preview box at the top of the form</li><li>The Icon Picker dialog will open</li><li>Browse through available icons or use the search function</li><li>Click on your desired icon to select it</li><li>The dialog will close and the selected icon will appear in the preview</li></ol><h3 id="customizing-icon-colors" tabindex="-1">Customizing Icon Colors <a class="header-anchor" href="#customizing-icon-colors" aria-label="Permalink to &quot;Customizing Icon Colors&quot;">​</a></h3><p>Three color components can be customized:</p><ol><li><p><strong>Background</strong>: The color behind the icon</p><ul><li>Default: White (#FFFFFF) in light mode, Black (#000001) in dark mode</li><li>Affects the square container where the icon appears</li></ul></li><li><p><strong>Icon</strong>: The color of the icon itself</p><ul><li>Default: Dark gray (#353535) in light mode, White (#FFFFFF) in dark mode</li><li>Changes the actual icon color</li></ul></li><li><p><strong>Border</strong>: The outline color around the icon container</p><ul><li>Default: Dark gray (#353535) in light mode, Medium gray (#686868) in dark mode</li><li>Defines the border of the square container</li></ul></li></ol><h3 id="light-and-dark-mode-settings" tabindex="-1">Light and Dark Mode Settings <a class="header-anchor" href="#light-and-dark-mode-settings" aria-label="Permalink to &quot;Light and Dark Mode Settings&quot;">​</a></h3><p>To configure theme-specific appearances:</p><ol><li>Click the Light/Dark toggle button to switch between modes</li><li>Each mode has its own independent color settings</li><li>Use the color pickers to select colors for each component</li><li>The preview instantly updates to show how your selections look</li></ol><h2 id="knowledge-base-integration" tabindex="-1">Knowledge Base Integration <a class="header-anchor" href="#knowledge-base-integration" aria-label="Permalink to &quot;Knowledge Base Integration&quot;">​</a></h2><p>Web links can be associated with knowledge bases:</p><ol><li>Select one or more Knowledge Bases from the dropdown</li><li>This makes the link available when using those knowledge bases</li><li>The AI can suggest the link when answering questions related to selected knowledge bases</li><li>Not required, but recommended for better AI integration</li></ol><h2 id="publishing-configuration" tabindex="-1">Publishing Configuration <a class="header-anchor" href="#publishing-configuration" aria-label="Permalink to &quot;Publishing Configuration&quot;">​</a></h2><h3 id="tags-and-topics" tabindex="-1">Tags and Topics <a class="header-anchor" href="#tags-and-topics" aria-label="Permalink to &quot;Tags and Topics&quot;">​</a></h3><p>Categorize your link for better organization and discovery:</p><ol><li><p><strong>Tags</strong>: Add multiple relevant tags</p><ul><li>Type a tag and press Enter to add it</li><li>Select from existing tags or create new ones</li><li>Helps with filtering and organization</li><li>No limit to number of tags</li></ul></li><li><p><strong>Topic</strong>: Select a single primary topic</p><ul><li>Choose from pre-defined topic list</li><li>One topic per link for clear categorization</li><li>Used for reporting and analytics</li></ul></li></ol><h3 id="publishing-schedule" tabindex="-1">Publishing Schedule <a class="header-anchor" href="#publishing-schedule" aria-label="Permalink to &quot;Publishing Schedule&quot;">​</a></h3><p>Control when your link is visible to users:</p><ol><li><p><strong>Start Date</strong>: When the link becomes available</p><ul><li>Click to open a date/time picker</li><li>Optional - leave blank for immediate availability</li><li>Includes both date and time selection</li></ul></li><li><p><strong>End Date</strong>: When the link is no longer available</p><ul><li>Click to open a date/time picker</li><li>Optional - leave blank for permanent availability</li><li>Useful for temporary resources or time-limited promotions</li></ul></li></ol><h2 id="featured-content-configuration" tabindex="-1">Featured Content Configuration <a class="header-anchor" href="#featured-content-configuration" aria-label="Permalink to &quot;Featured Content Configuration&quot;">​</a></h2><h3 id="featured-content-settings" tabindex="-1">Featured Content Settings <a class="header-anchor" href="#featured-content-settings" aria-label="Permalink to &quot;Featured Content Settings&quot;">​</a></h3><p>Make your link stand out in featured sections:</p><ol><li>Toggle &quot;Featured Content Enabled&quot; to make the link eligible for featured display</li><li>When enabled, additional configuration options appear: <ul><li><strong>Featured Title</strong>: Attention-grabbing headline (may differ from link title)</li><li><strong>Featured Description</strong>: Brief summary to explain the link&#39;s value</li><li><strong>Featured Image URL</strong>: Web address of an image to display <ul><li>Must be a valid URL (https://...)</li><li>Best dimensions: 300px × 200px</li><li>Appears at the top of the featured card</li></ul></li></ul></li></ol><h3 id="featured-content-preview" tabindex="-1">Featured Content Preview <a class="header-anchor" href="#featured-content-preview" aria-label="Permalink to &quot;Featured Content Preview&quot;">​</a></h3><p>A live preview card shows how your featured content will appear:</p><ol><li>Updates in real-time as you modify settings</li><li>Shows exact layout and appearance of the featured card</li><li>Helps ensure your content looks appealing when featured</li></ol><h2 id="managing-existing-links" tabindex="-1">Managing Existing Links <a class="header-anchor" href="#managing-existing-links" aria-label="Permalink to &quot;Managing Existing Links&quot;">​</a></h2><h3 id="editing-links" tabindex="-1">Editing Links <a class="header-anchor" href="#editing-links" aria-label="Permalink to &quot;Editing Links&quot;">​</a></h3><p>To modify an existing link:</p><ol><li>Navigate to the link in the Content Manager</li><li>Click on the link to open it in the Web Link Manager</li><li>Make desired changes to any aspect of the link</li><li>Click &quot;Save&quot; to apply your changes</li></ol><h3 id="deleting-links" tabindex="-1">Deleting Links <a class="header-anchor" href="#deleting-links" aria-label="Permalink to &quot;Deleting Links&quot;">​</a></h3><p>To remove a link from the system:</p><ol><li>Click the &quot;Delete&quot; button in the top-right corner</li><li>A confirmation dialog will appear</li><li>Click &quot;Delete&quot; in the dialog to confirm</li><li>The link will be permanently removed</li></ol><h2 id="metadata-and-information" tabindex="-1">Metadata and Information <a class="header-anchor" href="#metadata-and-information" aria-label="Permalink to &quot;Metadata and Information&quot;">​</a></h2><p>The Meta Information panel provides additional details about the link:</p><ol><li>Click the expandable &quot;Meta Information&quot; panel at the bottom right</li><li>View technical information including: <ul><li>File Name: System name for the link</li><li>Content Type: Always &quot;Link&quot; for web links</li><li>File Extension: Always &quot;web&quot; for web links</li><li>Content ID: Unique identifier</li><li>AI Process Status: Current AI processing state</li><li>Creation Information: Date and user who created the link</li><li>Update Information: Date and user of last modification</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective web link management:</p><ol><li><p><strong>Clear Naming</strong>:</p><ul><li>Use descriptive, concise titles</li><li>Ensure titles make sense out of context</li><li>Avoid abbreviations unless widely recognized</li></ul></li><li><p><strong>Icon Selection</strong>:</p><ul><li>Choose icons that visually represent the link purpose</li><li>Ensure good contrast between icon and background</li><li>Test appearance in both light and dark modes</li></ul></li><li><p><strong>Link Description</strong>:</p><ul><li>Focus on why users would need this link</li><li>Include relevant keywords for AI matching</li><li>Keep descriptions under 200 characters for readability</li></ul></li><li><p><strong>Knowledge Base Association</strong>:</p><ul><li>Associate links with all relevant knowledge bases</li><li>Consider when the AI should suggest this link</li><li>Update associations when new knowledge bases are created</li></ul></li><li><p><strong>Featured Content</strong>:</p><ul><li>Use high-quality, relevant images</li><li>Write compelling but honest featured descriptions</li><li>Only feature truly important links to avoid clutter</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Icon colors not appearing correctly</p><ul><li>Toggle between light and dark modes to ensure both are configured</li><li>Clear your browser cache to ensure updated styles are loading</li><li>Verify color values are correctly formatted (hex codes)</li></ul><p><strong>Issue</strong>: Link URL validation fails</p><ul><li>Ensure URL includes http:// or https:// prefix</li><li>Check for spaces or special characters in the URL</li><li>Try opening the URL in a browser to verify it works</li></ul><p><strong>Issue</strong>: Cannot access Icon Picker</p><ul><li>Click directly on the icon preview box</li><li>Try refreshing the page and attempting again</li><li>Check your browser console for errors</li></ul><p><strong>Issue</strong>: Featured image not displaying</p><ul><li>Verify the image URL is accessible and correct</li><li>Ensure the URL is a direct link to an image (ends with .jpg, .png, etc.)</li><li>Check if the image host allows hotlinking</li></ul><p><strong>Issue</strong>: Cannot save link</p><ul><li>Verify all required fields are completed</li><li>Check URL format is valid</li><li>Ensure you have proper permissions to create/edit links</li></ul><hr><p>For additional assistance with web link management, please contact your system administrator or refer to the platform documentation.</p>',76)]))}const p=i(o,[["render",l]]);export{g as __pageData,p as default};
